def main():
    cs = json.load(open(LANG / "cs.json", encoding="utf-8"))
    sk = {k: SK.get(k, v) for k, v in cs.items()}
    unknown = [k for k in SK if k not in cs]
    if unknown:
        print("keys not in cs.json:", ", ".join(unknown))
    with open(LANG / "sk.json", "w", encoding="utf-8", newline="") as f:
        json.dump(sk, f, ensure_ascii=False, indent=1)
        f.write("\n")
    print(f"sk.json: {len(sk)} keys, {sum(1 for k in sk if sk[k] != cs[k])} differ from Czech")


if __name__ == "__main__":
    main()
